CustomField.formula:
/*First if completed same day*/
if( DateValue(Tracking_Start__c)=DateValue(Tracking_End_Formula__c),
/*Adjusts Closed Hour/Minute if it's before or after hours*/
if(Tracking_End_Hour__c<8, 8, if(Tracking_End_Hour__c>17, 17, Tracking_End_Hour__c))+
if(Tracking_End_Hour__c<8 || Tracking_End_Hour__c>17, 0, Minute(TimeValue(Tracking_End_Formula__c))/60)
-
/*Adjust Created Hour/Minute if it's before or after hours*/
(if(Tracking_Start_Hour__c<8, 8, if(Tracking_Start_Hour__c>17, 17, Tracking_Start_Hour__c))+
if(Tracking_Start_Hour__c<8 || Tracking_Start_Hour__c>17,0, Minute(TimeValue(Tracking_Start__c)))/60),



/*If not the same day, calcs hours of first day, if after hours or weekend rounds Created down and Completed up*/
if( Weekday(DateValue(Tracking_Start__c))=7 || Weekday(DateValue(Tracking_Start__c))=0 || Tracking_Start_Hour__c>=17 , 0,
/*If it's before hours, limit to 8 hours*/
if(Tracking_Start_Hour__c<8, 8, 17-(Tracking_Start_Hour__c))+
if(Tracking_Start_Hour__c<8 || Tracking_Start_Hour__c>17, 0, (Minute(TimeValue(Tracking_Start__c))/60))
)
+
/*Calcs days between and converts to hours by multiplying by 8 workhours*/
(CASE( WEEKDAY(DateValue(Tracking_Start__c)),
/*This excludes End Dates e.g. Mon Tuesday Wednesday = 1*/
1 , CASE( MOD( DateValue(Tracking_End_Formula__c)-DateValue(Tracking_Start__c),7),1,0,2,1,3,2,4,3,5,4,6,5,0),
2 , CASE( MOD( DateValue(Tracking_End_Formula__c)-DateValue(Tracking_Start__c),7),1,0,2,1,3,2,4,3,5,3,6,3,0),
3 , CASE( MOD( DateValue(Tracking_End_Formula__c)-DateValue(Tracking_Start__c),7),1,0,2,1,3,2,4,2,5,2,6,3,0),
4 , CASE( MOD( DateValue(Tracking_End_Formula__c)-DateValue(Tracking_Start__c),7),1,0,2,1,3,1,4,1,5,2,6,3,0),
5 , CASE( MOD( DateValue(Tracking_End_Formula__c)-DateValue(Tracking_Start__c),7),1,0,2,0,3,0,4,1,5,2,6,2,0),
6 , CASE( MOD( DateValue(Tracking_End_Formula__c)-DateValue(Tracking_Start__c),7),1,0,2,0,3,0,4,1,5,2,6,3,0),
7 , CASE( MOD( DateValue(Tracking_End_Formula__c)-DateValue(Tracking_Start__c),7),1,0,2,0,3,0,4,1,5,2,6,2,0),
999)
+
(FLOOR(( DateValue(Tracking_End_Formula__c) - DateValue(Tracking_Start__c) )/7)*5))*8
+
/*Calcs days at the end*/
/*If it's before hours, limit to 8 hours*/
if(Tracking_End_Hour__c<8, 0, if(Tracking_End_Hour__c>17, 17, Tracking_End_Hour__c-8))+
if(Tracking_End_Hour__c<8 || Tracking_End_Hour__c>17, 0, (Minute(TimeValue(Tracking_End_Formula__c))/60))

)
